static GtkWidget*status_view;
static void status_text(GtkWidget*v,const char*s){gtk_text_buffer_set_text(gtk_text_view_get_buffer(GTK_TEXT_VIEW(v)),s,-1);}
static char*read_command(const char*cmd){char*b=NULL;gchar*err=NULL;gint code;GError*e=NULL;if(!g_spawn_command_line_sync(cmd,&b,&err,&code,&e)){g_free(err);if(e){b=g_strdup(e->message);g_error_free(e);}return b?b:g_strdup("Unavailable");}if(code&&err&&*err){g_free(b);b=g_strdup(err);}g_free(err);return b?b:g_strdup("");}
static GtkWidget*status_page(const char*name,const char*subtitle,GtkWidget**box){GtkWidget*w=page(name,subtitle,box);status_view=gtk_text_view_new();gtk_text_view_set_editable(GTK_TEXT_VIEW(status_view),FALSE);gtk_text_view_set_cursor_visible(GTK_TEXT_VIEW(status_view),FALSE);gtk_text_view_set_monospace(GTK_TEXT_VIEW(status_view),TRUE);gtk_text_view_set_wrap_mode(GTK_TEXT_VIEW(status_view),GTK_WRAP_WORD_CHAR);GtkWidget*sc=gtk_scrolled_window_new(NULL,NULL);gtk_container_add(GTK_CONTAINER(sc),status_view);gtk_box_pack_start(GTK_BOX(*box),sc,TRUE,TRUE,0);return w;}
static void network_refresh(GtkButton*b,gpointer v){refresh_stats();GString*s=g_string_new("SHADOW NETWORK / CURRENT CONNECTION\n\n");g_string_append_printf(s,"Interface: %s\nAddress:   %s\nVPN:       %s\n\n",iftext,iptext,vpn);char*t=read_command("ip route show");g_string_append_printf(s,"ROUTES\n%s\n",t);g_free(t);gchar*dns=NULL;if(g_file_get_contents("/etc/resolv.conf",&dns,NULL,NULL)){g_string_append_printf(s,"DNS CONFIGURATION\n%s\n",dns);g_free(dns);}char*nm=g_find_program_in_path("nmcli");g_string_append(s,nm?"NetworkManager tools are installed. Check daemon state before changing connections.\n":"NetworkManager is not installed/active yet. The current connection is preserved.\n");g_free(nm);status_text(v,s->str);g_string_free(s,TRUE);}
static void network_page(void){GtkWidget*box;GtkWidget*w=status_page("SHADOW NETWORK","Connection, routing and DNS information",&box);network_refresh(NULL,status_view);GtkWidget*b=gtk_button_new_with_label("Refresh connection information");g_signal_connect(b,"clicked",G_CALLBACK(network_refresh),status_view);gtk_box_pack_start(GTK_BOX(box),b,FALSE,FALSE,0);char*editor=g_find_program_in_path("nm-connection-editor");if(editor){b=gtk_button_new_with_label("Manage NetworkManager connections");g_signal_connect(b,"clicked",G_CALLBACK(action),"nm-connection-editor");gtk_box_pack_start(GTK_BOX(box),b,FALSE,FALSE,0);}g_free(editor);gtk_widget_show_all(w);}
static void bluetooth_refresh(GtkButton*b,gpointer v){char*cmd=g_find_program_in_path("bluetoothctl");if(!cmd){status_text(v,"Bluetooth system service/tools are not installed yet.\n\nA VirtualBox guest also needs a Bluetooth adapter passed through to the VM. No adapter or connection is assumed.");return;}g_free(cmd);char*s=read_command("bluetoothctl show"),*d=read_command("bluetoothctl devices");char*t=g_strdup_printf("BLUETOOTH CONTROLLER\n%s\nKNOWN DEVICES\n%s",s,d);status_text(v,t);g_free(s);g_free(d);g_free(t);}
static void bluetooth_page(void){GtkWidget*box;GtkWidget*w=status_page("SHADOW BLUETOOTH","Controller and device status",&box);bluetooth_refresh(NULL,status_view);GtkWidget*b=gtk_button_new_with_label("Refresh Bluetooth status");g_signal_connect(b,"clicked",G_CALLBACK(bluetooth_refresh),status_view);gtk_box_pack_start(GTK_BOX(box),b,FALSE,FALSE,0);gtk_widget_show_all(w);}
static const char*audio_backend;
static void audio_change(GtkRange*r,gpointer p){int n=gtk_range_get_value(r);char cmd[256];if(!audio_backend)return;if(!strcmp(audio_backend,"wpctl"))snprintf(cmd,sizeof cmd,"wpctl set-volume @DEFAULT_AUDIO_SINK@ %d%%",n);else if(!strcmp(audio_backend,"pactl"))snprintf(cmd,sizeof cmd,"pactl set-sink-volume @DEFAULT_SINK@ %d%%",n);else snprintf(cmd,sizeof cmd,"amixer -q sset Master %d%%",n);GError*e=NULL;g_spawn_command_line_async(cmd,&e);if(e)g_error_free(e);}
static void audio_page(void){GtkWidget*box;GtkWidget*w=status_page("SHADOW AUDIO","Volume and available audio devices",&box);char*t=NULL;char*found=g_find_program_in_path("wpctl");if(found){audio_backend="wpctl";t=read_command("wpctl status");}else if((found=g_find_program_in_path("pactl"))){audio_backend="pactl";t=read_command("pactl info");}else if((found=g_find_program_in_path("amixer"))){audio_backend="amixer";t=read_command("amixer scontrols");}else{audio_backend=NULL;t=g_strdup("Audio control backend is not installed yet.\n\nThe audio libraries/player are being prepared; hardware and mixer access must be verified before claiming sound works.");}g_free(found);status_text(status_view,t);g_free(t);GtkWidget*scale_widget=gtk_scale_new_with_range(GTK_ORIENTATION_HORIZONTAL,0,100,1);gtk_range_set_value(GTK_RANGE(scale_widget),50);gtk_widget_set_sensitive(scale_widget,audio_backend!=NULL);g_signal_connect(scale_widget,"value-changed",G_CALLBACK(audio_change),NULL);gtk_box_pack_start(GTK_BOX(box),gtk_label_new("Master volume (%)"),FALSE,FALSE,0);gtk_box_pack_start(GTK_BOX(box),scale_widget,FALSE,FALSE,0);gtk_widget_show_all(w);}
